    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: StaticInvokeStringState, engine: Engine<StaticInvokeStringPolicy>, configurationBeforeExit: [StaticInvokeStringState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .running:
            cancelInvokesForState(&pendingInvokes, .running)
            sceInvokeChildFits?.stop()
            sceInvokeChildFits?.detachMesh()
            sceInvokeChildFits = nil
            activeInvokes["fits"] = nil
            sceInvokeDoneFits = false
            sceInvokeChildOver?.stop()
            sceInvokeChildOver?.detachMesh()
            sceInvokeChildOver = nil
            activeInvokes["over"] = nil
            sceInvokeDoneOver = false
            sceInvokeChildWide?.stop()
            sceInvokeChildWide?.detachMesh()
            sceInvokeChildWide = nil
            activeInvokes["wide"] = nil
            sceInvokeDoneWide = false
        default:
            break  // No invocations to cancel
        }
    }



